// Adapted from netzen support-ticketing-app/backend/SupportDesk.Api/Auth/ApiExceptionHandler.cs @ 3dbc36d with the review's F4 fix applied
// (astraupskill/06-SOLUTIONS-AND-REVIEW.md:31): generic detail for the 500 arm, real message logged.
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;
using SupportDesk.Api.Application;
using SupportDesk.Api.Domain;

namespace SupportDesk.Api.Auth;

public sealed class ApiExceptionHandler : IExceptionHandler
{
    private readonly IProblemDetailsService _problemDetails;
    private readonly ILogger<ApiExceptionHandler> _logger;

    public ApiExceptionHandler(IProblemDetailsService problemDetails, ILogger<ApiExceptionHandler> logger)
    {
        _problemDetails = problemDetails;
        _logger = logger;
    }

    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        var (statusCode, title) = exception switch
        {
            NotFoundException => (StatusCodes.Status404NotFound, "Not found"),
            ForbiddenException => (StatusCodes.Status403Forbidden, "Forbidden"),
            ConcurrencyException => (StatusCodes.Status409Conflict, "Concurrency conflict"),
            DomainException => (StatusCodes.Status400BadRequest, "Invalid request"),
            BadHttpRequestException => (StatusCodes.Status400BadRequest, "Invalid request"),
            _ => (StatusCodes.Status500InternalServerError, "Unexpected error")
        };

        // Known exceptions carry messages written for the client (e.g. the 409 version hint).
        // Anything else is logged with its real message and answered generically.
        var detail = statusCode == StatusCodes.Status500InternalServerError
            ? "An unexpected error occurred. Reference: " + httpContext.TraceIdentifier
            : exception.Message;
        if (statusCode == StatusCodes.Status500InternalServerError)
        {
            _logger.LogError(exception, "Unhandled exception for {Path}", httpContext.Request.Path);
        }

        httpContext.Response.StatusCode = statusCode;

        return await _problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = new ProblemDetails
            {
                Status = statusCode,
                Title = title,
                Detail = detail
            }
        });
    }
}

